sys_script_client.script:
function onLoad() {
   //Type appropriate comment here, and begin script below
   // 1. 获取当前表单状态：是否为新建记录
    var isNewRecord = g_form.isNewRecord();

    // 2. 获取关联请假单字段（必须通过请假单跳转才有值）
    var leaveNum = g_form.getValue('leave_num');

    // ============== 核心逻辑 ==============
    // 如果是【新建记录】且【没有关联请假单】→ 禁止编辑 + 弹窗
    if (isNewRecord && leaveNum == '') {
        // 弹窗提示用户
        alert("温馨提示：\n销假单不能直接新建！\n请从请假单页面点击【销假】按钮生成。");
        // ========== 强制关闭页面 ==========
        history.back();
    }
}
